import{_ as o,o as r,c as n,a5 as s}from"./chunks/framework.R-FQ1xZ2.js";const p=JSON.parse('{"title":"架构对比实验：从假数据到显著结论","description":"","frontmatter":{"title":"架构对比实验：从假数据到显著结论","order":8},"headers":[],"relativePath":"interview/architecture-ab.md","filePath":"interview/architecture-ab.md","lastUpdated":null}'),a={name:"interview/architecture-ab.md"};function e(d,t,g,l,i,h){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="架构对比实验-从假数据到显著结论" tabindex="-1">架构对比实验：从假数据到显著结论 <a class="header-anchor" href="#架构对比实验-从假数据到显著结论" aria-label="Permalink to &quot;架构对比实验：从假数据到显著结论&quot;">​</a></h1><blockquote><p><strong>一句话</strong>：这是整个项目里<strong>最能体现工程判断力</strong>的一段——我用四轮实验把&quot;多智能体到底值不值&quot;从一个漂亮的假数字，查成了一条统计显著的结论，中间修了三层根因。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">与 ⑱ 面试深挖的分工</p><p><a href="/learn/projects/yyhelp/17-interview.html">⑱ 面试深挖与口径</a> 是<strong>整个项目</strong>的口径表与追问链。 这一页只讲<strong>架构对比实验这一条线</strong>：数字链、根因、方法论、以及怎么讲。</p></div><h2 id="一、结论先行-先说结果-再讲过程" tabindex="-1">一、结论先行（先说结果，再讲过程） <a class="header-anchor" href="#一、结论先行-先说结果-再讲过程" aria-label="Permalink to &quot;一、结论先行（先说结果，再讲过程）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>multi</th><th>single</th><th>判定（Holm 校正后）</th></tr></thead><tbody><tr><td><strong>完成率</strong></td><td><strong>63.3%</strong></td><td><strong>77.5%</strong></td><td><strong>−14.2pp，p=0.00053 → REGRESSION（显著）</strong></td></tr><tr><td>tokens/问</td><td>4,708</td><td>5,379</td><td>multi 省 12.5%，p=0.00034 → IMPROVEMENT</td></tr><tr><td>墙钟/问</td><td>24.7s</td><td>17.3s</td><td>慢 1.43×，p≈0 → REGRESSION</td></tr></tbody></table><p><strong>口径</strong>：<strong>120 题 × 2 臂 = 240 条</strong>，v4-pro 主模型、语义检索、盲测裁判（含锚定校准）；题集为 40 道原始题 × 3 个变体问法。</p><p><strong>一句话判读</strong>：用 12.5% 的 token 省量，换来 <strong>14.2pp 的完成率损失 + 43% 的延迟增加</strong>——对在线客服场景是明确的亏。</p><h2 id="二、四轮数字链-这一段本身就是面试素材" tabindex="-1">二、四轮数字链（这一段本身就是面试素材） <a class="header-anchor" href="#二、四轮数字链-这一段本身就是面试素材" aria-label="Permalink to &quot;二、四轮数字链（这一段本身就是面试素材）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>轮次</th><th>完成了什么</th><th>完成率 multi / single</th><th>当时的判定</th></tr></thead><tbody><tr><td>Gate-1 / ab2</td><td>首轮 40 题配对盲测</td><td><strong>100% / 97.5%</strong></td><td><strong>假数据</strong>（见第三节）</td></tr><tr><td>ab3</td><td>修三层根因后重跑</td><td>60% / 75%</td><td>边缘不显著（p=0.057）</td></tr><tr><td>ab4 / ab4-r2</td><td>修生成层缺陷 + 评测精度修正</td><td>72.5% / 77.5% → 70% / 77.5%</td><td>打平（p=0.26~0.42）</td></tr><tr><td>ab5</td><td>修工具数据源 + 性能优化</td><td><strong>70% / 70%</strong>（δ=0.000）</td><td>完全打平</td></tr><tr><td><strong>ab6</strong></td><td><strong>扩样到 120 题（40 题 × 3 变体）</strong></td><td><strong>63.3% / 77.5%</strong></td><td><strong>显著 REGRESSION</strong></td></tr></tbody></table><p><strong>为什么 40 题打平、120 题显著？两个原因</strong>：</p><ol><li><strong>功效</strong>：n=40 时置信区间是 [−14pp, +14pp]，真实的 −14.2pp 恰好落在<strong>可检出边界外</strong>；n=120 把边界压到 ±11pp。</li><li><strong>变体暴露了脆弱性</strong>（见第五节）：换问法后 multi 掉 6.7pp，single 稳定——<strong>这才是差异的真正来源</strong>。</li></ol><h2 id="三、三层根因-第一轮的数字为什么是假的" tabindex="-1">三、三层根因（第一轮的数字为什么是假的） <a class="header-anchor" href="#三、三层根因-第一轮的数字为什么是假的" aria-label="Permalink to &quot;三、三层根因（第一轮的数字为什么是假的）&quot;">​</a></h2><p>首轮我把&quot;40/40 vs 39/40，不显著&quot;写成结论。后来做人工锚定抽样（15 题逐条核对答案与标准答案），发现三层问题叠加：</p><h3 id="根因-1-检索后端从未接入-接线缺口" tabindex="-1">根因 1：检索后端从未接入（接线缺口） <a class="header-anchor" href="#根因-1-检索后端从未接入-接线缺口" aria-label="Permalink to &quot;根因 1：检索后端从未接入（接线缺口）&quot;">​</a></h3><p><code>.env</code> 里 <code>YYHELP_KB_RETRIEVE</code> 没设 → 默认 <code>stub</code> → <strong>整场 A/B 跑的是&quot;关键词替身&quot;</strong>（对一份硬编码政策列表做子串+单字重叠打分），Day1 建好的 163 切片语义检索<strong>根本没接上</strong>。</p><p><strong>怎么发现的</strong>：诊断脚本直连检索器，发现&quot;改约收费&quot;&quot;丢件赔付&quot;这类题<strong>两臂齐声说&#39;知识库没有&#39;</strong>，而 KB 里明明有对应 chunk——<strong>两臂同时失败 = 共同前置坏了</strong>。</p><p><strong>修法</strong>：<code>.env</code> 显式 <code>semantic</code>；并加<strong>前置闸</strong>：A/B 跑题前检查检索后端，不是 semantic 就直接退出。</p><h3 id="根因-2-向量路静默降级-配置漂移" tabindex="-1">根因 2：向量路静默降级（配置漂移） <a class="header-anchor" href="#根因-2-向量路静默降级-配置漂移" aria-label="Permalink to &quot;根因 2：向量路静默降级（配置漂移）&quot;">​</a></h3><p>即使切到 semantic，<code>YYHELP_HF_HOME</code> 指向一个<strong>空目录</strong> → embedding 模型每次加载都去联网重试下载（超时）→ 向量路失效，检索<strong>静默退化成只有 BM25</strong>。</p><p><strong>怎么发现的</strong>：独立 benchmark 测 encode 耗时，发现单条 query 稳态只要 <strong>0.03 秒</strong>而首次要 12 秒——<strong>12 秒是模型加载</strong>，而当时的&quot;慢&quot;其实是联网重试。</p><p><strong>修法</strong>：修正缓存路径 + 补齐模型权重（镜像 8 段并行下载，字节数精确校验）；加<strong>第二道前置闸</strong>：embedder 维度必须等于集合维度，不等就退出。</p><h3 id="根因-3-裁判在放水-评测层" tabindex="-1">根因 3：裁判在放水（评测层） <a class="header-anchor" href="#根因-3-裁判在放水-评测层" aria-label="Permalink to &quot;根因 3：裁判在放水（评测层）&quot;">​</a></h3><p>原来的裁判 rubric 写着&quot;<strong>诚实说明无法回答并给出可行下一步 = 满分</strong>&quot;——于是<strong>检索失败 + 礼貌拒答被判成完成任务</strong>。更难查的是：裁判会<strong>用自己的先验当事实</strong>（把&quot;退款 3-7 个工作日&quot;这种幻觉判成正确，因为它的先验里这句话&quot;听起来合理&quot;）。</p><p><strong>修法两条</strong>：</p><ul><li><strong>rubric 分层</strong>：有确定答案的题，只有给出正确事实才得分；拒答/查不到一律 0 分。超范围题反之。</li><li><strong>锚定题 + 参考事实</strong>：裁判队列尾部混入 <strong>5 条已知标签的锚定题</strong>，锚定不全对就<strong>整批标签作废</strong>（退出码 2）；同时把标准答案 chunk 作为&quot;参考知识&quot;喂给裁判，让它从&quot;判断&quot;变成&quot;核对&quot;。</li></ul><blockquote><p>⚠️ <strong>一个副作用</strong>：修完 rubric 后完成率从 97.5% 掉到 60-75%——<strong>这不是模型变差了，是数字终于真的了</strong>。这一条要主动讲。</p></blockquote><h2 id="四、方法论-可以迁移到任何-a-b-项目" tabindex="-1">四、方法论（可以迁移到任何 A/B 项目） <a class="header-anchor" href="#四、方法论-可以迁移到任何-a-b-项目" aria-label="Permalink to &quot;四、方法论（可以迁移到任何 A/B 项目）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>具体做法</th><th>为什么必须</th></tr></thead><tbody><tr><td><strong>配对检验 + 多重比较校正</strong></td><td>同题两臂配对（t + Wilcoxon），多指标用 Holm 校正</td><td>单方法显著不敢下结论；多指标不校正会把噪声当发现</td></tr><tr><td><strong>功效分析</strong></td><td>用不一致对占比 ψ 反推&quot;要多少题才能测出 X pp&quot;</td><td>没有它，&quot;不显著&quot;到底是&quot;没差异&quot;还是&quot;样本不够&quot;永远说不清</td></tr><tr><td><strong>锚定校准</strong></td><td>已知标签题混入评测队列，全对才采信</td><td>裁判本身是模型，会漂移、会被自己的先验带偏</td></tr><tr><td><strong>参考事实注入</strong></td><td>给裁判标准答案文本，而非让它凭常识判断</td><td>LLM 裁判<strong>不核实事实</strong>，rubric 再严也拦不住&quot;合理幻觉&quot;</td></tr><tr><td><strong>前置闸门</strong></td><td>跑题前检查：检索后端 / 模型维度 / 端到端 smoke</td><td>配置漂移是静默的，事后靠人工抽样发现代价太大</td></tr><tr><td><strong>共同前置优先</strong></td><td>两臂同时失败的题，先查它们共用的那一层</td><td>本项目的教训：检索和裁判坏了，测什么架构都是白测</td></tr></tbody></table><p><strong>功效数字（务必带口径）</strong>：ψ=0.208 时，测 <strong>+5pp 需 652 题</strong>、+10pp 需 161 题、+20pp 需 39 题——所以 <strong>−14.2pp 在 120 题下可检出，而小幅差异仍不可判</strong>。</p><h2 id="五、新发现-multi-的脆弱点在分派鲁棒性" tabindex="-1">五、新发现：multi 的脆弱点在分派鲁棒性 <a class="header-anchor" href="#五、新发现-multi-的脆弱点在分派鲁棒性" aria-label="Permalink to &quot;五、新发现：multi 的脆弱点在分派鲁棒性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>同一批题的两种问法</th><th>multi 完成率</th><th>single 完成率</th></tr></thead><tbody><tr><td>原题（40 题）</td><td>70.0%</td><td>70.0%</td></tr><tr><td>变体问法（120 题）</td><td><strong>63.3%（−6.7pp）</strong></td><td><strong>77.5%（+7.5pp）</strong></td></tr></tbody></table><p><strong>解释</strong>：multi 的收益依赖<strong>分派正确</strong>（意图分类 → 计划 → 专家），而分派对口语变体不鲁棒——问法一变就可能派错专家，而派错的专家工具集不匹配，答不出。single 用一个全工具专家，对问法天然更稳。</p><p><strong>这条比&quot;完成率更低&quot;更有解释力</strong>：multi 的成本不只是 token 和延迟，还有<strong>路由脆弱性</strong>。改进方向也由此而来：不是&quot;多加专家&quot;，而是<strong>让分派对问法不敏感</strong>（规则兜底 + 口语归一化）。</p><h2 id="六、面试怎么讲-三档-两条追问链" tabindex="-1">六、面试怎么讲（三档 + 两条追问链） <a class="header-anchor" href="#六、面试怎么讲-三档-两条追问链" aria-label="Permalink to &quot;六、面试怎么讲（三档 + 两条追问链）&quot;">​</a></h2><h3 id="_30-秒版" tabindex="-1">30 秒版 <a class="header-anchor" href="#_30-秒版" aria-label="Permalink to &quot;30 秒版&quot;">​</a></h3><blockquote><p>我给这个项目做了架构对比实验：让多智能体和单智能体<strong>共享同一套骨架</strong>，只把&quot;谁决定下一个专家&quot;这一个变量分开，跑 <strong>120 题 × 2 臂</strong>的配对盲测。结论是<strong>多智能体完成率显著低 14.2 个百分点、延迟高 43%，只在 token 上省 12.5%</strong>——所以我保持单智能体为主。</p><p>更有价值的是过程：这个结论我是<strong>修掉三层根因之后</strong>才拿到的，第一版数字是假的。</p></blockquote><h3 id="_2-分钟版-加根因" tabindex="-1">2 分钟版（加根因） <a class="header-anchor" href="#_2-分钟版-加根因" aria-label="Permalink to &quot;2 分钟版（加根因）&quot;">​</a></h3><blockquote><p>第一版我拿到的是&quot;完成率 100% vs 97.5%、不显著&quot;。后来做人工锚定抽样发现三层问题：<strong>检索后端从来没接上</strong>（跑的是关键词替身）、<strong>向量路因为一个环境变量指向空目录而静默降级</strong>、<strong>裁判把&quot;礼貌拒答&quot;判成完成任务</strong>。</p><p>修完之后完成率掉到 60-75%——<strong>这才是真实水平</strong>。第二版结论是&quot;打平&quot;，我又扩样到三个问法变体，差异才达到统计显著。</p><p>整个过程我沉淀了两条纪律：<strong>共同前置坏了就别谈架构对比</strong>；<strong>裁判本身也要被校准</strong>。</p></blockquote><h3 id="两条追问链" tabindex="-1">两条追问链 <a class="header-anchor" href="#两条追问链" aria-label="Permalink to &quot;两条追问链&quot;">​</a></h3><p><strong>追问链 A：「你是不是为了得出想要的结论才改评测？」</strong></p><blockquote><p>「反过来说更准确——我是<strong>先发现问题才改的</strong>。三个改动都不是我主动想改：检索后端没接上是我读代码发现的；环境变量指向空目录是 benchmark 测出来的；裁判放水是人工核对答案时发现的。 而且我保留了反向证据：<strong>修 rubric 让完成率从 97.5% 掉到 60-75%</strong>，如果我想美化数据，最该删的就是这个改动。 另外每轮的数字都写在台账里，包括中间那两轮&quot;打平&quot;的——<strong>没有一轮是我事后挑出来的</strong>。」</p></blockquote><p><strong>追问链 B：「40 题说打平，120 题说显著，哪个可信？」</strong></p><blockquote><p>「120 题更可信，但<strong>不是我挑样本挑出来的</strong>，是功效算出来的。n=40 的时候置信区间是 ±14pp，真实的 −14.2pp 刚好在边界外——<strong>测不出不等于没差异</strong>，这句话在我 40 题那版结论里就写着了。 扩样用的是<strong>同 40 题的三个问法变体</strong>（语义一致、gt 复用），不是为了凑数。 而且扩样暴露了我原本没意识到的机制：<strong>multi 在变体问法上掉 6.7pp 而 single 稳定</strong>——差异来自分派鲁棒性，不是模型能力。」</p></blockquote><h2 id="七、红线-这一段绝对不能说过头" tabindex="-1">七、红线（这一段绝对不能说过头） <a class="header-anchor" href="#七、红线-这一段绝对不能说过头" aria-label="Permalink to &quot;七、红线（这一段绝对不能说过头）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>不能说</th><th>该怎么说</th></tr></thead><tbody><tr><td>&quot;多智能体没用 / 是伪需求&quot;</td><td>「<strong>在这批任务、这个实现质量下</strong>，多智能体没有完成率收益且延迟显著更高；它的脆弱点在分派鲁棒性」</td></tr><tr><td>&quot;我证明了架构选型&quot;</td><td>「这是<strong>单场景、离线题集、合成语料</strong>上的结论；触发条件（问题跨域占比、延迟预算、分派鲁棒性）满足时需要重测」</td></tr><tr><td>&quot;AI 客服就该用单智能体&quot;</td><td>「<strong>决定性变量是问题分布与延迟预算，不是行业名</strong>——跨域占比高的场景结论可能相反」</td></tr><tr><td>&quot;我早就发现问题了&quot;</td><td>「第一版数字是假的，是<strong>锚定抽样</strong>把它揭穿的——这一点我写在复盘的第一段」</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/learn/projects/yyhelp/17-interview.html">⑱ 面试深挖与口径</a>——项目整体口径表</li><li><a href="/learn/projects/yyhelp/11-evaluation.html">⑫ 评测与回归门禁</a>——评测体系与门禁</li><li><a href="/learn/interview/cheatsheet.html">🔥 面试随身数字卡</a>——所有可报数字总表</li><li><a href="/learn/interview/agent.html">Agent 与工具调用高频题</a>——多智能体/工具调用的通用知识</li></ul>',47)])])}const c=o(a,[["render",e]]);export{p as __pageData,c as default};
